'use strict';

// A screen commit (build-screen) stays inside one slice's web/ folder, plus what composing it needs:
//
//   web/src/slices/{slice}/**    the slice's part: a form per command, a view per read model, its index.ts
//                                (the parts the page shows), handlers.ts (mock responses from its scenarios)
//                                and its tests
//   web/src/lib/api-types.ts     regenerated by `npm run gen:api`, never edited by hand
//   web/src/providers/{name}/**  another system's browser library behind a module of ours (ADR-044), created by the
//                                first screen that needs it and shared by the others
//
// Nothing else: never a page (web/src/pages/, web/src/navigation.json: the model owns them, ADR-069), not the app
// shell, web/src/lib/, the mocks, the kit's components (web/src/components/: ui atoms and patterns, ADR-072) or config, and no backend file (the backend step commits on its
// own). The slice's folder also needs a test.

const fs = require('fs');
const path = require('path');

const WEB_SLICE = /^web\/src\/slices\/([^/]+)\//;
const PAGES = /^web\/src\/(pages\/|navigation\.json$)/;
const COMPONENTS = /^web\/src\/components\//;
const ALLOWED = [
  /^web\/src\/lib\/api-types\.ts$/,   // generated client types
  /^web\/src\/providers\/[^/]+\//,     // another system's browser library, behind our module (ADR-044)
];

module.exports = {
  name: 'web-scope',
  scope: 'web',
  run(ctx) {
    const violations = [];
    const slices = new Set();
    for (const { path: p } of ctx.changes) {
      const m = p.match(WEB_SLICE);
      if (m) slices.add(m[1]);
    }
    const primary = [...slices].sort()[0];

    for (const { path: p } of ctx.changes) {
      const m = p.match(WEB_SLICE);
      if (m) {
        if (m[1] !== primary) {
          violations.push({ path: p, reason: `touches the screen of slice "${m[1]}" but this commit's scope is "${primary}" — split into separate commits` });
        }
        continue;
      }
      if (ALLOWED.some((r) => r.test(p))) continue;
      if (COMPONENTS.test(p)) {
        violations.push({
          path: p,
          reason: 'the kit\'s components (web/src/components/: the ui atoms, the patterns, ADR-072): a part uses them and never changes them. If a part needs one that isn\'t there, block with request-feedback: the kit adds it',
        });
        continue;
      }
      if (PAGES.test(p)) {
        violations.push({
          path: p,
          reason: 'a page: the model owns every page (ADR-069). The slice only exports its parts from web/src/slices/{slice}/index.ts, and the page shows them where navigation.json says. If the page needs something else, block with request-feedback: the model changes, not the page',
        });
        continue;
      }
      violations.push({
        path: p,
        reason: 'outside web/src/slices/{slice}/, web/src/lib/api-types.ts and a provider\'s module (web/src/providers/{name}/) — a screen commit changes nothing else',
      });
    }

    const dir = path.join(ctx.repoRoot, 'web/src/slices', primary);
    let files = [];
    try {
      files = fs.readdirSync(dir);
    } catch {
      return violations; // the folder is deleted in this commit
    }
    if (!files.some((f) => /\.test\.tsx?$/.test(f))) {
      violations.push({ path: `web/src/slices/${primary}/`, reason: 'no *.test.tsx: each form and view needs tests from the slice\'s scenarios' });
    }
    return violations;
  },
};
